css:
.cal {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  grid-auto-rows: 44px;
  gap: 4px;
  max-width: 420px;
  padding: 12px;
  border: 1px solid #d4d4d8;
  border-radius: 8px;
}

.dow {
  align-self: end;
  text-align: center;
  font-size: 12px;
  font-weight: 600;
  color: #52525b;
}

.day {
  display: grid;
  place-items: center;
  border: 1px solid #e4e4e7;
  border-radius: 6px;
  background: #fafafa;
}

.start {
  grid-column: 3; /* the first day falls on Wednesday */
}

.today {
  background: #f97316;
  color: #fff;
  border-color: #f97316;
}
